 "id": "pathanat-intro",
 "subject": "pathanat",
 "group": "General pathology",
 "title": "Introduction to pathology",
 "sourceFile": "Introduction to Pathology.pdf (General Pathology, Prof. Amal Damiri)",
 "sourceUrl": "https://drive.google.com/file/d/1NmTowkypGoOlgd2V-71mZmj3J0r8zP02/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> Slides that only show pictures are covered in outline. If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "What pathology is",
   "html": "<p><strong>Pathology</strong> (Greek: study of diseases) is the branch of medicine studying structural and functional changes in tissues and organs caused by disease. It sits at the interface of basic sciences (anatomy, physiology, biochemistry) and clinical sciences (surgery, oncology, internal medicine, etc.), providing the scientific foundation for diagnosis and treatment.</p><p>Anatomical pathology is practised only by pathologist physicians (unlike general medical analyses, which biologists — physicians or pharmacists — can also perform).</p>"
  },
  {
   "id": "s1",
   "title": "What it studies: lesions",
   "html": "<p>Pathology studies <strong>visible modifications (lesions)</strong> caused by disease, at three levels: <em>macroscopic</em> (naked eye/magnifying glass), <em>microscopic tissue</em> level (pathological histology) and <em>microscopic cellular</em> level (pathological cytology). A <strong>lesion</strong> is any structural damage or abnormal change caused by disease; an <strong>elementary lesion</strong> affects one structure, a <strong>lesional complex</strong> combines several. Lesions may be malformative, inflammatory/immune, circulatory (e.g. atherosclerosis), or neoplastic (e.g. adenocarcinoma).</p>"
  },
  {
   "id": "s2",
   "title": "Classification and branches",
   "html": "<p>Traditionally split into <strong>general pathology</strong> (basic mechanisms: cell injury, inflammation/repair, haemodynamic disorders, growth disorders/neoplasia) and <strong>systematic pathology</strong> (how these mechanisms play out in each organ system). Branches include histopathology, cytopathology, molecular pathology and forensic pathology; human pathology (patient tissue) is distinguished from experimental pathology (animal models, cell culture).</p>"
  },
  {
   "id": "s3",
   "title": "Disease process: aetiology, pathogenesis, lesion, clinic",
   "html": "<p>Four linked aspects explain a disease: <strong>aetiology</strong> (the cause — \"why\"; known cause = primary, unknown = idiopathic; genetic or acquired — infectious, nutritional, chemical, physical), <strong>pathogenesis</strong> (the mechanism — \"how\" the cause produces disease), <strong>morphological changes/lesions</strong> (the resulting structural alterations, gross or microscopic), and <strong>clinical manifestations</strong> (the symptoms/signs, course and prognosis that follow from those structural changes).</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Term</th><th scope='col'>Meaning</th><th scope='col'>Example</th></tr></thead><tbody><tr><th scope='row'>Aetiology</th><td>The cause</td><td>HPV in cervical cancer; idiopathic if unknown</td></tr><tr><th scope='row'>Pathogenesis</th><td>The mechanism</td><td>Incubation period of an infection</td></tr><tr><th scope='row'>Lesion</th><td>Structural change</td><td>Cirrhotic nodules, granuloma</td></tr><tr><th scope='row'>Clinical manifestations</th><td>Symptoms and signs</td><td>Jaundice, cough, fever</td></tr></tbody></table></div>"
  },
  {
   "id": "s4",
   "title": "The diagnostic process",
   "html": "<p>Anatomical pathology reasons by <strong>analogy</strong>: comparing normal histology with pathological tissue, then correlating findings with clinical data and imaging/biology (the <strong>anatomo-clinical correlation</strong>). Tools: macroscopic examination, optical (photonic) microscopy, plus immunohistochemistry, molecular biology and (rarely) electron microscopy. Roles of pathology: <strong>diagnostic</strong> (anatomo-clinical diagnosis), <strong>prognostic</strong> (e.g. pTNM staging, margin status in cancer), <strong>therapeutic response</strong> (regression/persistence/worsening of lesions), and <strong>research</strong> (treatment efficacy).</p>"
  }
 ],
