 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define pathology in one sentence.",
   "back": "The branch of medicine studying the structural and functional changes in tissues and organs caused by disease, at macroscopic and microscopic level."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Aetiology vs pathogenesis — what's the difference?",
   "back": "Aetiology = the CAUSE of disease (why it arises); pathogenesis = the MECHANISM by which that cause produces disease (how it develops)."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "What is a lesion, and what's the difference between an elementary lesion and a lesional complex?",
   "back": "A lesion is any structural damage/abnormal change caused by disease. An elementary lesion affects one structure; a lesional complex is an association of several elementary lesions."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "General pathology vs systematic pathology?",
   "back": "General pathology studies basic disease mechanisms (cell injury, inflammation, circulatory disorders, neoplasia). Systematic pathology applies these mechanisms to specific organ systems."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Match the pioneer to their contribution: Morgagni, Virchow, Vesalius, Pasteur/Koch, Van Leeuwenhoek.",
   "back": "Morgagni: linked disease to organ changes (founded anatomic pathology). Virchow: father of cellular pathology. Vesalius: corrected Galenic anatomy (1543). Pasteur & Koch: germ theory of disease. Van Leeuwenhoek: invented the microscope."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What are the three levels at which lesions are examined?",
   "back": "Macroscopic (naked eye/magnifying glass), microscopic-tissue (pathological histology), microscopic-cellular (pathological cytology)."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "What does 'anatomo-clinical correlation' mean and why does it matter?",
   "back": "Correlating the pathologist's morphological findings with the patient's clinical data and paraclinical tests (imaging, biology) — essential for reaching a synthetic diagnosis."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Name the four roles of pathology in patient care.",
   "back": "Diagnostic (establishing the diagnosis), prognostic (e.g. pTNM staging in cancer), evaluating response to therapy, and supporting research protocols."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Primary vs idiopathic aetiology?",
   "back": "Primary = the cause of disease is known. Idiopathic = the cause is unknown."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Human pathology vs experimental pathology?",
   "back": "Human pathology examines structural abnormalities in patient tissue (gross and microscopic). Experimental pathology studies cellular processes using animal models and tissue/cell cultures."
  },
  {
   "id": "x0",
   "type": "text",
   "front": "What does 'anatomical pathology' study, in the simplest terms?",
   "back": "Any visible modification (lesion) in the body caused by disease — to the naked eye (macroscopy) or under the microscope (histology for tissues, cytology for cells)."
  },
  {
   "id": "x1",
   "type": "text",
   "front": "Who were Morgagni, Virchow and Vesalius?",
   "back": "Morgagni linked diseases to organ changes (founded anatomic pathology). Virchow: father of cellular pathology. Vesalius: corrected Galen's anatomy in 1543."
  },
  {
   "id": "x2",
   "type": "text",
   "front": "What are the four categories of lesions shown in the lecture?",
   "back": "Malformative (e.g. arteriovenous malformation), inflammatory/immune (e.g. lung tuberculosis), circulatory (e.g. atherosclerosis), neoplastic (e.g. adenocarcinoma)."
  },
  {
   "id": "x3",
   "type": "text",
   "front": "Why must the request form be complete?",
   "back": "Because the clinical features, course and prognosis guide the pathologist's diagnostic process — the form is the pathologist's 'patient interview'."
  },
  {
   "id": "x4",
   "type": "text",
   "front": "What is the course of a disease?",
   "back": "The stages of its natural history in the absence of intervention — for infections: incubation, prodrome, illness, decline, convalescence."
  },
  {
   "id": "x5",
   "type": "text",
   "front": "What did the clinical case teach?",
   "back": "A lung nodule in a man with prior prostate cancer; IHC PSA+ and TTF-1− showed a solitary lung metastasis from prostate adenocarcinoma — pathology changes the diagnosis and the treatment."
  },
  {
   "id": "x6",
   "type": "text",
   "front": "Name four famous pathologists and their eponym.",
   "back": "Papanicolaou (Pap smear), Langerhans (islets/cells), Hodgkin (Hodgkin disease), Reed (Reed-Sternberg cells), Spitz (Spitz naevus), Call-Exner bodies, Piringer-Kuchinka lymphadenitis."
  },
  {
   "id": "x7",
   "type": "text",
   "front": "How is pathology positioned among medical sciences?",
   "back": "As the vital link between basic sciences (anatomy, physiology, biochemistry, pharmacology) and clinical sciences (medicine, surgery, neurology, dermatology)."
  },
  {
   "id": "x8",
   "type": "text",
   "front": "Four future directions of pathology?",
   "back": "Digital pathology for remote diagnosis, AI-driven predictions, single-cell sequencing, spatial transcriptomics."
  },
  {
   "id": "x9",
   "type": "text",
   "front": "What are the four aspects of a disease process pathology covers?",
   "back": "Aetiology, pathogenesis, molecular and morphological changes, functional alterations/clinical manifestations."
  },
  {
   "id": "img-etiology",
   "type": "image",
   "target": "etiology",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Aetiology. The cause of disease: primary if known, idiopathic if unknown; genetic or acquired."
  },
  {
   "id": "img-pathogenesis",
   "type": "image",
   "target": "pathogenesis",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Pathogenesis. The mechanism by which the cause produces structural and functional abnormalities."
  },
  {
   "id": "img-morphology",
   "type": "image",
   "target": "morphology",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Morphological changes (lesion). Gross or microscopic structural alterations that follow the pathogenetic mechanism."
  },
  {
   "id": "img-clinical",
   "type": "image",
   "target": "clinical",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Clinical manifestations. Symptoms and signs, course and prognosis determined by the lesions."
  },
  {
   "id": "img-diagnosis",
   "type": "image",
   "target": "diagnosis",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Anatomo-clinical diagnosis. Correlating the lesion with clinical, biological and imaging data."
  },
  {
   "id": "img-prognosis",
   "type": "image",
   "target": "prognosis",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Prognosis and treatment. Pathology's roles: diagnosis, prognostic evaluation, response to therapy, research."
  }
 ],
 "deeper": [
  {
   "title": "Why 'idiopathic' is not the end of the story",
   "html": "<p>Calling a disease idiopathic means the cause is unknown today, not unknowable. Many conditions once labelled idiopathic — peptic ulcer, cervical cancer, Burkitt lymphoma — moved to the 'primary aetiology' column once H. pylori, HPV and EBV were identified. The lecture's own history section shows the pattern: each generation's idiopathic list shrinks as techniques improve.</p><p class='src'>Source: the lecture's aetiology and history slides.</p>"
  },
  {
   "title": "Why the pathologist needs the clinician",
   "html": "<p>The lecture insists on the anatomo-clinical correlation because a lesion rarely has one meaning. A granuloma may be tuberculosis, sarcoidosis, a foreign body or a fungus; the age, exposure history and imaging decide. That is why the request form is described as the pathologist's patient interview, and why an incomplete form can lead to a wrong or delayed diagnosis.</p><p class='src'>Source: the lecture's diagnostic process slides.</p>"
  }
 ],
