 "deeper": [
  {
   "title": "Why calcium is the executioner",
   "html": "<p>Healthy cells keep cytoplasmic calcium ten thousand times lower than the outside, using ATP-driven pumps. When ATP runs out, calcium floods in and switches on the enzymes the cell normally keeps locked: phospholipases that dissolve membranes, proteases that cut the cytoskeleton, endonucleases that fragment DNA, and ATPases that waste the last ATP. That is the lecture's 'three reasons too much calcium is bad', and it explains why the mitochondria, already starved, are poisoned as well.</p><p class='src'>Source: the lecture's pathogenesis slides.</p>"
  },
  {
   "title": "Why the liver gets fatty",
   "html": "<p>Hepatocytes handle most of the body's fat traffic: they take up fatty acids, oxidise them, or package them into lipoproteins for export. Alcohol, hypoxia, malnutrition and toxins each block one of these steps, so triglyceride accumulates in vacuoles. Because the liver does so much lipid work, it is the organ where fatty change is most common, as the lecture notes.</p><p class='src'>Source: the lecture's fatty change slide.</p>"
  }
 ],
