 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define necrosis.",
   "back": "Cell death with severe membrane damage: lysosomal enzymes digest the cell, contents leak out and elicit inflammation. Always pathological and irreversible."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Define apoptosis.",
   "back": "Programmed cell death: the cell activates caspases that degrade its own DNA and proteins, fragments into membrane-bound apoptotic bodies that are phagocytosed without inflammation."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Three nuclear changes of necrosis, in order?",
   "back": "Pyknosis (shrinkage/condensation) → karyorrhexis (fragmentation) → karyolysis (dissolution). The nucleus disappears in 1–2 days."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Six patterns of tissue necrosis and one example each.",
   "back": "Coagulative (infarct, except brain); liquefactive (abscess, brain infarct); caseous (TB); gangrenous (ischaemic limb); fat necrosis (pancreatitis, breast trauma); fibrinoid (polyarteritis nodosa)."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Necrosis vs apoptosis: cell size, membrane, inflammation, role?",
   "back": "Necrosis: enlarged, disrupted membrane, inflammation yes, always pathological. Apoptosis: reduced, intact membrane, no inflammation, often physiological."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Give four physiological causes of apoptosis.",
   "back": "Embryogenesis; involution of hormone-dependent tissues (menstrual endometrium, breast after weaning); turnover of intestinal crypt cells; removal of neutrophils/lymphocytes after inflammation or immune response; CTL killing of infected or tumour cells."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Give three pathological causes of apoptosis.",
   "back": "DNA damage (radiation, cytotoxic drugs); accumulation of misfolded proteins; some viral infections (adenovirus, HIV)."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Which caspases are activators and which are executioners?",
   "back": "Activators: 2, 8, 9, 10. Executioners: 3, 6, 7 (DNA fragmentation, chromatin condensation, membrane changes)."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Intrinsic vs extrinsic apoptosis pathway?",
   "back": "Intrinsic (mitochondrial, most frequent): internal triggers, BCL-2 vs Bax/Bak balance, caspase 9. Extrinsic (death receptor): external signal, Fas/FasL, caspase 8."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "How do BCL-2 and p53 relate to cancer?",
   "back": "BCL-2 overexpression (follicular lymphoma) blocks apoptosis. p53 guards the G1/S checkpoint and triggers Bax-mediated apoptosis when DNA damage is irreparable; p53 mutations are common in cancers. Therapies: anti-BCL2 drugs, chemo/radiotherapy."
  },
  {
   "id": "x0",
   "type": "text",
   "front": "What determines the cell's response to aggression?",
   "back": "The cause, severity and duration of the aggression, and the type and adaptive capacity of the cell."
  },
  {
   "id": "x1",
   "type": "text",
   "front": "Why does necrosis cause inflammation but apoptosis does not?",
   "back": "Necrosis ruptures the membrane and spills contents that elicit a host reaction; apoptotic bodies keep an intact membrane and are cleared before leaking."
  },
  {
   "id": "x2",
   "type": "text",
   "front": "Cytoplasmic changes of necrosis?",
   "back": "Increased eosinophilia (denatured proteins bind eosin, RNA loss removes basophilia) and a homogeneous glassy look from glycogen loss."
  },
  {
   "id": "x3",
   "type": "text",
   "front": "Causes of necrosis?",
   "back": "Anoxia/ischaemia, physical agents, chemicals and drugs, infections, immune reactions, nutritional imbalance."
  },
  {
   "id": "x4",
   "type": "text",
   "front": "Coagulative vs liquefactive necrosis?",
   "back": "Coagulative: architecture preserved, anucleate ghosts, infarcts except brain. Liquefactive: complete enzymatic digestion into liquid, infections and brain infarcts."
  },
  {
   "id": "x5",
   "type": "text",
   "front": "Where is fat necrosis seen?",
   "back": "Acute pancreatitis (activated lipases in the peritoneum, an emergency) and breast trauma (cytosteatonecrosis)."
  },
  {
   "id": "x6",
   "type": "text",
   "front": "Physiological roles of apoptosis in immunity?",
   "back": "Removing neutrophils after acute inflammation, lymphocytes after an immune response, and killing infected/neoplastic cells via cytotoxic T lymphocytes."
  },
  {
   "id": "x7",
   "type": "text",
   "front": "How do BCL-2 and Bax/Bak interact?",
   "back": "BCL-2 is anti-apoptotic and prevents Bax/Bak from permeabilising mitochondria; p53 activates Bax when DNA damage is irreparable."
  },
  {
   "id": "x8",
   "type": "text",
   "front": "What does Fas ligand do?",
   "back": "Membrane protein on activated T lymphocytes that engages Fas death receptors on target cells, activating caspase 8 (extrinsic pathway)."
  },
  {
   "id": "x9",
   "type": "text",
   "front": "Recap: how does necrosis compare with apoptosis in frequency and extent?",
   "back": "Necrosis is less frequent, involves many cells, may not be localised, is uncontrolled and pathological, with inflammation; apoptosis is often single cells, controlled, no inflammation."
  },
  {
   "id": "img-injury",
   "type": "image",
   "target": "injury",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Irreversible injury. Severe or progressive stress beyond repair."
  },
  {
   "id": "img-necrosis",
   "type": "image",
   "target": "necrosis",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Necrosis. Enzymes leak, cell bursts, contents spill out."
  },
  {
   "id": "img-apoptosis",
   "type": "image",
   "target": "apoptosis",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Apoptosis. Programmed suicide; the membrane stays intact."
  },
  {
   "id": "img-inflammation",
   "type": "image",
   "target": "inflammation",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Inflammation. Leaked contents attract leukocytes; only after necrosis."
  },
  {
   "id": "img-intrinsic",
   "type": "image",
   "target": "intrinsic",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Intrinsic (mitochondrial) pathway. The most frequent; balance of BCL-2 versus Bax/Bak; converges on caspase 9."
  },
  {
   "id": "img-extrinsic",
   "type": "image",
   "target": "extrinsic",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Extrinsic (death receptor) pathway. Outside signal such as FasL on activated T cells; caspase 8."
  },
  {
   "id": "img-executioner",
   "type": "image",
   "target": "executioner",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Executioner caspases. 3, 6 and 7 fragment DNA and reshape the cell."
  },
  {
   "id": "img-phagocytosis",
   "type": "image",
   "target": "phagocytosis",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Clearance of apoptotic bodies. Macrophages remove fragments before anything leaks."
  }
 ],
 "deeper": [
  {
   "title": "Why brain infarcts liquefy",
   "html": "<p>The brain has little extracellular collagen to hold a coagulated scaffold together, and its cells are rich in lysosomal enzymes and lipids. After ischaemia, microglia and leukocytes digest the dead tissue completely, leaving a fluid-filled cyst. That is why the lecture lists the brain as the one solid organ whose infarcts are liquefactive rather than coagulative.</p><p class='src'>Source: the lecture's patterns of necrosis slides.</p>"
  },
  {
   "title": "Why blocking apoptosis can cause cancer without fast growth",
   "html": "<p>Follicular lymphoma cells do not divide unusually fast. The t(14;18) translocation puts BCL-2 under the immunoglobulin heavy-chain promoter, so the cells simply refuse to die. Over years they accumulate, which is why the disease is indolent and why anti-BCL2 drugs, rather than classical antiproliferative chemotherapy, target its root cause.</p><p class='src'>Source: the lecture's clinical significance slide.</p>"
  }
 ],
