 "deeper": [
  {
   "title": "Why pus is yellow-white and thick",
   "html": "<p>Pus is mostly dead neutrophils. After they have discharged their granules against bacteria, they die by apoptosis or necrosis, and their DNA, proteases and membrane debris make a viscous, protein-rich fluid. The lecture's 'pyocytes' with pyknotic nuclei are these exhausted cells, and the creamy colour comes from the sheer number of them together with myeloperoxidase.</p><p class='src'>Source: the lecture's suppurative inflammation slides.</p>"
  },
  {
   "title": "Why streptococcal infections spread as phlegmon rather than abscess",
   "html": "<p>An abscess forms when the body walls off infection with fibrin and granulation tissue. Streptococci secrete hyaluronidase, which dissolves the hyaluronic acid of the matrix, and streptokinase, which dissolves fibrin. Nothing can contain the infection, so neutrophils and bacteria spread along fascial planes: the diffuse, dangerous picture the lecture calls phlegmon.</p><p class='src'>Source: the lecture's phlegmon slide.</p>"
  }
 ],
