 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Three layers of a blood vessel and their contents?",
   "back": "Intima: endothelium (internal elastic lamina below). Media: smooth muscle (external elastic lamina). Adventitia: connective tissue with nerves and vasa vasorum."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Starling forces: what pushes fluid out and what pulls it in?",
   "back": "Capillary hydrostatic pressure pushes fluid out (higher at the arteriolar end); plasma oncotic pressure (albumin) pulls it in (dominant at the venular end); interstitial pressures oppose; lymphatics drain the residual excess."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Transudate vs exudate?",
   "back": "Transudate: protein <3 g/dL, few cells, clear, SG <1.016, non-inflammatory (heart failure, cirrhosis, nephrotic). Exudate: protein >3 g/dL, many cells, cloudy, SG >1.020, inflammatory (infection, cancer)."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Five major mechanisms of oedema with an example each.",
   "back": "↑Hydrostatic pressure (heart failure, DVT); ↓oncotic pressure (nephrotic syndrome, cirrhosis); ↑permeability (inflammation, burns); lymphatic obstruction (mastectomy, filariasis); Na/water retention (renal failure, hyperaldosteronism)."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "How is oedema classified?",
   "back": "By distribution: localised vs generalised (anasarca). By composition: transudative vs exudative. By physical character: pitting (cardiac/renal/hepatic) vs non-pitting (lymphoedema, lipoedema, myxoedema)."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Inflammatory vs haemodynamic oedema?",
   "back": "Inflammatory: ↑permeability via histamine, bradykinin, TNF-α, IL-1 → protein-rich exudate with neutrophils and fibrin. Haemodynamic: altered Starling forces → protein-poor transudate (cardiogenic, renal, hepatic)."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Causes and signs of pulmonary oedema?",
   "back": "Left heart failure, ARDS, toxin inhalation, severe infection, high altitude (HAPE). Dyspnoea, wheeze, pink frothy sputum; may coexist with pleural effusion."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Causes and signs of cerebral oedema?",
   "back": "Trauma, stroke, meningitis/encephalitis, tumour, hyponatraemia, toxins. Headache, confusion, seizures, coma; macroscopically narrow sulci and flat gyri."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Define lymphoedema and give causes.",
   "back": "Non-pitting swelling from lymphatic damage or blockage: surgery (radical mastectomy), radiation, cancer, filariasis (elephantiasis), or congenital. Persistent heaviness and skin thickening."
  },
  {
   "id": "x0",
   "type": "text",
   "front": "Arteries by type?",
   "back": "Large elastic (aorta, elastin-rich media), medium muscular (coronary, renal, smooth-muscle media), small arteries and arterioles within organs."
  },
  {
   "id": "x1",
   "type": "text",
   "front": "Regulation of haemodynamics?",
   "back": "Neural (baroreceptors, chemoreceptors, sympathetic/parasympathetic), hormonal (RAAS, ADH), local (autoregulation, nitric oxide, endothelin)."
  },
  {
   "id": "x2",
   "type": "text",
   "front": "Consequences of vascular wall changes?",
   "back": "Narrowing: slow (atherosclerosis → atrophy/infarction) or acute (thrombus/embolus → infarction). Weakening: dilatation, dissection, rupture."
  },
  {
   "id": "x3",
   "type": "text",
   "front": "Body water distribution?",
   "back": "60% of body weight is water; two-thirds intracellular, one-third extracellular (intravascular, interstitial, transcellular)."
  },
  {
   "id": "x4",
   "type": "text",
   "front": "Normal fluid circulation in one sentence?",
   "back": "Hydrostatic pressure at the arteriolar end pushes fluid out, oncotic pressure at the venular end pulls it back, and lymphatics drain the small residue."
  },
  {
   "id": "x5",
   "type": "text",
   "front": "Mechanism of oedema by sodium retention?",
   "back": "Hypovolaemia → renal vasoconstriction, ↓GFR, ↑renin/aldosterone and ↑ADH → retention of Na and water → oedema."
  },
  {
   "id": "x6",
   "type": "text",
   "front": "Localised vs generalised oedema?",
   "back": "Localised: trauma, infection/cellulitis, insect bites, DVT — swelling, redness, pain, warmth. Generalised (anasarca): heart, kidney, liver failure, protein deficiency."
  },
  {
   "id": "x7",
   "type": "text",
   "front": "What is pitting oedema and its causes?",
   "back": "Indentation persists after pressure; from water retention in heart, kidney, liver disease, DVT, varicose veins, thrombophlebitis, pregnancy."
  },
  {
   "id": "x8",
   "type": "text",
   "front": "Types of haemodynamic oedema?",
   "back": "Cardiogenic (venous congestion), renal (nephrotic hypoalbuminaemia, sodium retention), hepatic (cirrhosis)."
  },
  {
   "id": "x9",
   "type": "text",
   "front": "Peripheral oedema causes?",
   "back": "Venous insufficiency, congestive heart failure, kidney disease, lymphatic obstruction; also age, pregnancy, hypertension."
  },
  {
   "id": "img-arteriolar",
   "type": "image",
   "target": "arteriolar",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Arteriolar end. Hydrostatic pressure from the heart pushes fluid out."
  },
  {
   "id": "img-capillary",
   "type": "image",
   "target": "capillary",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Capillary. Endothelium without media; the site of exchange."
  },
  {
   "id": "img-venular",
   "type": "image",
   "target": "venular",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Venular end. Plasma oncotic pressure from albumin pulls fluid back."
  },
  {
   "id": "img-lymphatic",
   "type": "image",
   "target": "lymphatic",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Lymphatic drainage. Removes the small residual excess of interstitial fluid."
  },
  {
   "id": "img-hydro",
   "type": "image",
   "target": "hydro",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Increased hydrostatic pressure. Heart failure, DVT, venous obstruction."
  },
  {
   "id": "img-oncotic",
   "type": "image",
   "target": "oncotic",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Reduced oncotic pressure. Nephrotic syndrome, cirrhosis, malnutrition."
  },
  {
   "id": "img-perm",
   "type": "image",
   "target": "perm",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Increased permeability. Inflammation, burns: protein-rich exudate."
  },
  {
   "id": "img-lymph",
   "type": "image",
   "target": "lymph",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Lymphatic obstruction. Lymphoedema after mastectomy, filariasis, tumour."
  },
  {
   "id": "img-sodium",
   "type": "image",
   "target": "sodium",
   "front": "What is at the arrow, and why does it matter?",
   "back": "Sodium and water retention. Renal failure, hyperaldosteronism via renin, aldosterone and ADH."
  }
 ],
 "deeper": [
  {
   "title": "Why heart failure swells the ankles and cirrhosis swells the belly",
   "html": "<p>In right heart failure, blood backs up in the veins, raising hydrostatic pressure most where gravity adds to it, so fluid leaks into the ankles first and pits on pressure. In cirrhosis, albumin production falls and portal pressure rises at the same time, so fluid escapes across the peritoneal capillaries into the abdomen as ascites. Same Starling law, different force and different site.</p><p class='src'>Source: the lecture's hydrostatic and oncotic pressure slides.</p>"
  },
  {
   "title": "Why lymphoedema does not pit",
   "html": "<p>Lymph carries protein. When lymphatics are blocked, protein accumulates in the interstitium and pulls water with it, and chronic protein-rich fluid stimulates fibroblasts and fat deposition. The tissue becomes firm and thick, so a fingertip no longer leaves a dent — the non-pitting, skin-thickening oedema of filariasis or post-mastectomy arms.</p><p class='src'>Source: the lecture's lymphatic obstruction and non-pitting oedema slides.</p>"
  }
 ],
