   "front": "Precursor lesions: sure vs possible?",
   "back": "Sure (genetic): familial adenomatous polyposis, xeroderma pigmentosum. Possible (acquired): colonic adenoma, ulcerative colitis, bladder papilloma, gastric atrophy, cirrhosis."
