 "deeper": [
  {
   "title": "Why one mutated allele is enough for an oncogene but not a suppressor",
   "html": "<p>An oncogene is an accelerator stuck on: one hyperactive copy of KRAS or EGFR keeps signalling regardless of the normal copy, so the mutation behaves as dominant. A suppressor is a brake, and one working copy of RB or TP53 is still enough to stop the cell; both copies must be lost, which is why inherited retinoblastoma needs a germline hit plus a second somatic hit. The lecture's 'gain of function bad' versus 'loss of function bad' summarises this logic.</p><p class='src'>Source: the lecture's oncogene and tumour suppressor slides.</p>"
  },
  {
   "title": "Why carcinomas take the lymphatic road and sarcomas the blood",
   "html": "<p>Epithelia sit on a basement membrane that lymphatic capillaries, with their open, valve-less junctions, penetrate easily, so carcinoma cells reach nodes first. Sarcomas grow inside mesenchyme rich in thin-walled venules and directly invade them, so they seed the lungs by blood. The exceptions the lecture names, renal cell and follicular thyroid carcinoma, are epithelial tumours that classically invade veins.</p><p class='src'>Source: the lecture's routes of metastasis slides.</p>"
  }
 ],
